//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(accesstoken.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *AccessTokenUpsertBulk) UpdateNewValues() *AccessTokenUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(accesstoken.FieldID)
			}
			if _, exists := b.mutation.UserID(); exists {
				s.SetIgnore(accesstoken.FieldUserID)
			}
			if _, exists := b.mutation.Name(); exists {
				s.SetIgnore(accesstoken.FieldName)
			}
			if _, exists := b.mutation.TokenHash(); exists {
				s.SetIgnore(accesstoken.FieldTokenHash)
			}
			if _, exists := b.mutation.Audience(); exists {
				s.SetIgnore(accesstoken.FieldAudience)
			}
			if _, exists := b.mutation.Scopes(); exists {
				s.SetIgnore(accesstoken.FieldScopes)
			}
			if _, exists := b.mutation.Roles(); exists {
				s.SetIgnore(accesstoken.FieldRoles)
			}
			if _, exists := b.mutation.AuthVersion(); exists {
				s.SetIgnore(accesstoken.FieldAuthVersion)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(accesstoken.FieldCreatedAt)
			}
			if _, exists := b.mutation.ExpiresAt(); exists {
				s.SetIgnore(accesstoken.FieldExpiresAt)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
